14. // DockerContainer implements DESIGN §9.6 (D-steps). Works on linux (sh) and
15. // windows (PS) targets; docker CLI presence gated in Preflight (D14).
16. type DockerContainer struct{}
17. 
18. func (d *DockerContainer) shell(t transport.Transport) transport.Shell {
19. 	if t.OS() == spec.OSWindows {
20. 		return transport.ShellPowerShell
21. 	}
22. 	return transport.ShellSh
23. }
24. 
25. func (d *DockerContainer) run(ctx context.Context, t transport.Transport, step, script string, env map[string]string, timeout int) (transport.Result, error) {
26. 	r, err := t.Exec(ctx, transport.Cmd{Shell: d.shell(t), Script: script, Env: env, TimeoutSec: timeout})
27. 	if err != nil {
28. 		return r, stepErr("ERR_CONNECT", t.Host(), step, err)
29. 	}
30. 	return r, nil
31. }
32. 
33. func (d *DockerContainer) Preflight(ctx context.Context, t transport.Transport, rc ReleaseCtx) error {
34. 	r, err := d.run(ctx, t, "PREFLIGHT", `docker version --format '{{.Server.Version}}'`, nil, 60)
35. 	if err != nil {
36. 		return err
37. 	}
38. 	if r.ExitCode != 0 {
39. 		return stepErr("ERR_PREFLIGHT", t.Host(), "PREFLIGHT",
40. 			fmt.Errorf("docker daemon unavailable: %s", truncOut(r)))
41. 	}
42. 	return nil
43. }
44. 
45. // imageRef resolves tag-vs-digest (DESIGN §6.3 docker_registry).
46. func imageRef(a *spec.Artifact) string {
47. 	src := a.Source
48. 	if src.Digest != "" {
49. 		return src.Image + "@" + src.Digest
50. 	}
51. 	tag := src.Tag
52. 	if tag == "" {
53. 		tag = a.Version
54. 	}
55. 	return src.Image + ":" + tag
56. }
57. 
58. // Pull = D1+D2 (+D7 logout). Login credentials travel via env/stdin only.
59. func (d *DockerContainer) Pull(ctx context.Context, t transport.Transport, rc ReleaseCtx) error {
60. 	a := &rc.Spec.Artifact
61. 	ref := imageRef(a)
62. 	registry := ""
63. 	if i := strings.Index(a.Source.Image, "/"); i > 0 && strings.ContainsAny(a.Source.Image[:i], ".:") {
64. 		registry = a.Source.Image[:i]
65. 	}
66. 	env := map[string]string{}
67. 	login, logout := "", ""
68. 	if a.Source.Auth.Username != "" && a.Source.Auth.PasswordEnv != "" {
69. 		env["LD_REG_PW"] = os.Getenv(a.Source.Auth.PasswordEnv)
70. 		if t.OS() == spec.OSWindows {
71. 			login = fmt.Sprintf(`$env:LD_REG_PW | docker login %s -u %s --password-stdin
72. if($LASTEXITCODE -ne 0){ Write-Error 'docker login failed'; exit 40 }`, registry, psq(a.Source.Auth.Username))
73. 			logout = fmt.Sprintf("docker logout %s | Out-Null", registry)
74. 		} else {
75. 			login = fmt.Sprintf(`printf '%%s' "$LD_REG_PW" | docker login %s -u '%s' --password-stdin || { echo 'docker login failed' >&2; exit 40; }`, registry, a.Source.Auth.Username)
76. 			logout = fmt.Sprintf("docker logout %s >/dev/null 2>&1 || true", registry)
77. 		}
78. 	}
79. 	var script string
80. 	if t.OS() == spec.OSWindows {
81. 		script = fmt.Sprintf(`%s
82. docker pull %s
83. $code=$LASTEXITCODE
84. %s
85. if($code -ne 0){ exit 40 }
86. exit 0`, login, ref, logout)
87. 	} else {
88. 		script = fmt.Sprintf(`%s
89. docker pull '%s'; code=$?
90. %s
91. [ $code -eq 0 ] || exit 40
92. exit 0`, login, ref, logout)
93. 	}
94. 	r, err := d.run(ctx, t, "FETCH", script, env, 1800)
95. 	if err != nil {
96. 		return err
97. 	}
98. 	if r.ExitCode != 0 {
99. 		return stepErr("ERR_ARTIFACT_FETCH", t.Host(), "FETCH", fmt.Errorf("%s", truncOut(r)))
100. 	}
101. 	return nil
102. }
103. 
104. // CurrentImageID = D3, "" when container absent.
105. func (d *DockerContainer) CurrentImageID(ctx context.Context, t transport.Transport, rc ReleaseCtx) (string, error) {
106. 	name := rc.Spec.Pattern.ContainerName
107. 	var script string
108. 	if t.OS() == spec.OSWindows {
109. 		script = fmt.Sprintf(`docker inspect -f '{{.Image}}' %s 2>$null
110. if($LASTEXITCODE -ne 0){ Write-Output '' }
111. exit 0`, name)
112. 	} else {
113. 		script = fmt.Sprintf(`docker inspect -f '{{.Image}}' '%s' 2>/dev/null || echo ''`, name)
114. 	}
115. 	r, err := d.run(ctx, t, "STAGE", script, nil, 60)
116. 	if err != nil {
117. 		return "", err
118. 	}
119. 	return strings.TrimSpace(r.Stdout), nil
120. }
121. 
122. func (d *DockerContainer) runArgs(rc ReleaseCtx) string {
123. 	p := rc.Spec.Pattern
124. 	restart := p.RestartPolicy
125. 	if restart == "" {
126. 		restart = "unless-stopped"
127. 	}
128. 	var b strings.Builder
129. 	fmt.Fprintf(&b, "-d --name %s --restart %s", p.ContainerName, restart)
130. 	for _, pt := range p.Ports {
131. 		fmt.Fprintf(&b, " -p %s", pt)
132. 	}
133. 	keys := make([]string, 0, len(rc.Env))
134. 	for k := range rc.Env {
135. 		keys = append(keys, k)
136. 	}
137. 	sort.Strings(keys)
138. 	for _, k := range keys {
139. 		fmt.Fprintf(&b, " -e %s", shellKV(k, rc.Env[k]))
140. 	}
141. 	for _, v := range p.Volumes {
142. 		fmt.Fprintf(&b, " -v %s", v)
143. 	}
144. 	for _, a := range p.RunArgs {
145. 		fmt.Fprintf(&b, " %s", a)
146. 	}
147. 	return b.String()
148. }
149. 
150. func shellKV(k, v string) string { return "\"" + k + "=" + strings.ReplaceAll(v, `"`, `\"`) + "\"" }
