152. // RunNew = D4+D5 with a given image ref (new ref, or old image id on rollback).
153. func (d *DockerContainer) RunNew(ctx context.Context, t transport.Transport, rc ReleaseCtx, ref string) error {
154. 	name := rc.Spec.Pattern.ContainerName
155. 	var script string
156. 	if t.OS() == spec.OSWindows {
157. 		script = fmt.Sprintf(`docker rm -f %s 2>$null | Out-Null
158. docker run %s %s
159. if($LASTEXITCODE -ne 0){ exit %d }
160. exit 0`, name, d.runArgs(rc), ref, ExitServiceStart)
161. 	} else {
162. 		script = fmt.Sprintf(`docker rm -f '%s' >/dev/null 2>&1 || true
163. docker run %s '%s' || exit %d
164. exit 0`, name, d.runArgs(rc), ref, ExitServiceStart)
165. 	}
166. 	r, err := d.run(ctx, t, "START", script, nil, 300)
167. 	if err != nil {
168. 		return err
169. 	}
170. 	if r.ExitCode != 0 {
171. 		return failFrom(t.Host(), "START", r)
172. 	}
173. 	return nil
174. }
