199. 	name := rc.Spec.Pattern.ContainerName
200. 	var script string
201. 	if t.OS() == spec.OSWindows {
202. 		script = fmt.Sprintf(`$s = docker inspect -f '{{.State.Running}}' %s 2>$null
203. if($LASTEXITCODE -ne 0){ Write-Output 'not_installed'; exit 0 }
204. if($s -match 'true'){ Write-Output 'running' } else { Write-Output 'stopped' }
205. exit 0`, name)
206. 	} else {
207. 		script = fmt.Sprintf(`s=$(docker inspect -f '{{.State.Running}}' '%s' 2>/dev/null) || { echo not_installed; exit 0; }
208. [ "$s" = "true" ] && echo running || echo stopped`, name)
209. 	}
210. 	r, err := d.run(ctx, t, "STATUS", script, nil, 60)
211. 	if err != nil {
212. 		return "", err
213. 	}
214. 	return strings.TrimSpace(r.Stdout), nil
215. }
216. 
