 	ref := imageRef(a)
 	registry := ""
 	if i := strings.Index(a.Source.Image, "/"); i > 0 && strings.ContainsAny(a.Source.Image[:i], ".:") {
 		registry = a.Source.Image[:i]
 	}
 	env := map[string]string{}
