 		env["LD_REG_PW"] = os.Getenv(a.Source.Auth.PasswordEnv)
 		if t.OS() == spec.OSWindows {
 			login = fmt.Sprintf(`$env:LD_REG_PW | docker login %s -u %s --password-stdin
