 func TestWindowsServiceS4Golden(t *testing.T) {
 	var w WindowsService
 	restart := true
 	rc := winsvcRC(spec.Pattern{
 		Type:        spec.PatternWindowsService,
 		ServiceName: "PaymentsSvc",
 		DisplayName: "Contoso Payments",
