 	iVer := strings.Index(xml, `name="LD_VERSION"`)
 	if !(iAsp < iApp && iApp < iVer) {
 		t.Errorf("WinSW <env> entries must be deterministically sorted, got order asp=%d app=%d ver=%d:\n%s", iAsp, iApp, iVer, xml)
 	}
 }

