150. // Scenario: stop escalates to a STRUCTURED FORCE_KILL step (DESIGN §9.2 S2,
151. // WSV-07). The graceful S1 STOP script and the S2 taskkill script must be
152. // emitted as two distinct steps; when the kill still can't stop the service
153. // the error must be tagged step=FORCE_KILL / code=ERR_SERVICE_STOP (43), NOT
154. // hidden inside the STOP step.
155. func TestWindowsServiceStopForceKill(t *testing.T) {
156. 	var w WindowsService
157. 	rc := winsvcRC(spec.Pattern{
158. 		Type:               spec.PatternWindowsService,
159. 		ServiceName:        "SlowSvc",
160. 		StopTimeoutSeconds: 10,
161. 	}, nil)
162. 
163. 	// graceful stop times out (sentinel 100) → force-kill succeeds (0).
164. 	fk := &scriptTransport{osKind: spec.OSWindows, queue: []transport.Result{{ExitCode: 100}, {ExitCode: 0}}}
165. 	if err := w.Stop(context.Background(), fk, rc); err != nil {
166. 		t.Fatalf("Stop with successful force-kill should succeed: %v", err)
167. 	}
168. 	if len(fk.scripts) != 2 {
169. 		t.Fatalf("Stop must emit a graceful STOP script then a separate FORCE_KILL script, got %d", len(fk.scripts))
170. 	}
171. 	if !strings.Contains(fk.scripts[0], "Stop-Service") || strings.Contains(fk.scripts[0], "taskkill") {
172. 		t.Errorf("first script must be the graceful STOP (no taskkill):\n%s", fk.scripts[0])
173. 	}
174. 	if !strings.Contains(fk.scripts[1], "taskkill /PID") || !strings.Contains(fk.scripts[1], "/T /F") {
175. 		t.Errorf("second script must be the FORCE_KILL taskkill step:\n%s", fk.scripts[1])
176. 	}
177. 	// The old defect emitted a bare `Write-Output 'FORCE_KILL'` inside the STOP
178. 	// step instead of a real step; guard against its return.
179. 	if strings.Contains(fk.scripts[0], "Write-Output 'FORCE_KILL'") {
180. 		t.Errorf("FORCE_KILL must be a structured step, not text inside STOP:\n%s", fk.scripts[0])
181. 	}
182. 
183. 	// graceful stop times out, force-kill also fails (exit 43) → structured error.
184. 	fkFail := &scriptTransport{osKind: spec.OSWindows, queue: []transport.Result{{ExitCode: 100}, {ExitCode: ExitServiceStop}}}
185. 	err := w.Stop(context.Background(), fkFail, rc)
186. 	if err == nil {
187. 		t.Fatal("Stop must fail when force-kill cannot stop the service")
188. 	}
189. 	var se *StepError
190. 	if !errors.As(err, &se) {
191. 		t.Fatalf("expected *StepError, got %T: %v", err, err)
192. 	}
193. 	if se.Step != "FORCE_KILL" {
194. 		t.Errorf("force-kill failure must be tagged step=FORCE_KILL, got %q", se.Step)
195. 	}
196. 	if se.Code != "ERR_SERVICE_STOP" {
197. 		t.Errorf("force-kill failure must map to ERR_SERVICE_STOP, got %q", se.Code)
198. 	}
199. 
200. 	// already stopped/absent → single graceful STOP, no force-kill step.
201. 	fkNoop := &scriptTransport{osKind: spec.OSWindows, queue: []transport.Result{{ExitCode: 0}}}
202. 	if err := w.Stop(context.Background(), fkNoop, rc); err != nil {
203. 		t.Fatalf("Stop no-op should succeed: %v", err)
204. 	}
205. 	if len(fkNoop.scripts) != 1 {
206. 		t.Errorf("stopped service must not run the FORCE_KILL step, got %d scripts", len(fkNoop.scripts))
207. 	}
208. }
