// imageRef resolves tag-vs-digest (DESIGN §6.3 docker_registry).
func imageRef(a *spec.Artifact) string {
	src := a.Source
	if src.Digest != "" {
		return src.Image + "@" + src.Digest
	}
	tag := src.Tag
	if tag == "" {
		tag = a.Version
	}
	return src.Image + ":" + tag
}

