 	host := t.Host()
 	sl = sl.forHost(host)
 	started := time.Now().UTC()
 	if m != nil && m.CurrentVersion == s.Artifact.Version {
 		if st, err := dc.Status(ctx, t, rc); err == nil && st == "running" {
 			return statusFrom(m, host, st), nil
 		}
 	}
