func TestDockerRunArgMetacharSafe(t *testing.T) {
	inj := "$(touch pwned)`id`$HOME he'llo"
	pat := dockerPattern()
	src := spec.Source{Type: "docker_registry", Image: "registry.example.com/app", Tag: "2.0.0"}

