25. func (n *dockerNode) Exec(ctx context.Context, c transport.Cmd) (transport.Result, error) {
26. 	s := c.Script
27. 	switch {
28. 	case strings.Contains(s, "docker pull"):
29. 		if n.pullErr {
30. 			return transport.Result{ExitCode: 40, Stderr: "pull failed"}, nil
31. 		}
32. 		return ok(""), nil
33. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.Image}}"):
34. 		return ok(n.image), nil
35. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.State.Running}}"):
36. 		if n.image == "" {
37. 			return ok("not_installed"), nil
38. 		}
39. 		return ok("running"), nil
40. 	case strings.Contains(s, "docker run"):
41. 		n.runScripts = append(n.runScripts, s)
42. 		if n.runErr {
43. 			return transport.Result{ExitCode: 44, Stderr: "run failed"}, nil
44. 		}
45. 		// Reflect the image the container now runs: a rollback run (ref == the
46. 		// recorded old image id) restores rollbackImage; a normal run switches to
47. 		// runImage. This lets healthGate distinguish new-vs-restored by n.image.
48. 		switch {
49. 		case n.rollbackImage != "" && strings.Contains(s, n.rollbackImage):
50. 			n.image = n.rollbackImage
51. 		case n.runImage != "":
52. 			n.image = n.runImage
53. 		}
54. 		return ok(""), nil
55. 	case strings.Contains(s, "docker stop"):
56. 		return ok(""), nil
57. 	}
58. 	return n.fakeHost.Exec(ctx, c)
59. }
