func (d *DockerContainer) Uninstall(ctx context.Context, t transport.Transport, rc ReleaseCtx, purge bool) error {
	qn := d.q(t, rc.Spec.Pattern.ContainerName)
	var script string
	if t.OS() == spec.OSWindows {
