exit 0`, d.q(t, name), d.runArgs(t, rc), d.q(t, ref), ExitServiceStart)
	}
	r, err := d.run(ctx, t, "START", script, nil, 300)
	if err != nil {
		return err
	}
	if r.ExitCode != 0 {
		return failFrom(t.Host(), "START", r)
	}
	return nil
}

