+		Auth:  spec.SourceAuth{Username: "svc", PasswordEnv: "LD_REG_PW_ENV"},
+	}, nil)
+	fp := &scriptTransport{osKind: spec.OSLinux}
+	if err := d.Pull(context.Background(), fp, rc); err != nil {
+		t.Fatalf("Pull: %v", err)
+	}
+	if !strings.Contains(fp.scripts[0], "docker login 'localhost' -u 'svc' --password-stdin") {
+		t.Errorf("localhost must be recognized as the registry host in D1 login:\n%s", fp.scripts[0])
+	}
+	if !strings.Contains(fp.scripts[0], "docker logout 'localhost'") {
+		t.Errorf("D7 logout must target the localhost registry:\n%s", fp.scripts[0])
+	}
+	if strings.Contains(fp.scripts[0], "docker login -u") {
+		t.Errorf("login must not fall back to Docker Hub (empty registry):\n%s", fp.scripts[0])
+	}
