+	// no registry host is passed to login/logout.
+	rcHub := dockerRC(spec.OSLinux, dockerPattern(), spec.Source{
+		Type:  "docker_registry",
+		Image: "library/nginx",
+		Tag:   "2.0.0",
+		Auth:  spec.SourceAuth{Username: "svc", PasswordEnv: "LD_REG_PW_ENV"},
