	} else {
		script = fmt.Sprintf(`out=$(docker inspect -f '{{.Image}}' %s 2>&1); rc=$?
if [ $rc -eq 0 ]; then printf '%%s' "$out"; exit 0; fi
case "$out" in *"No such"*) exit 20;; esac
